/**
 * Search drugs by name, generic name, brand name, or indication.
 * @param {string} query
 * @returns {Array}
 */
export function searchDrugs(query) {
  if (!query) return DRUGS;
  const q = query.toLowerCase();
  return DRUGS.filter(d =>
    d.name.toLowerCase().includes(q) ||
    d.generic_name.toLowerCase().includes(q) ||
    (d.brand_names || []).some(b => b.toLowerCase().includes(q)) ||
    (d.indication || "").toLowerCase().includes(q) ||
    (d.drug_class || "").toLowerCase().includes(q) ||
    (d.therapeutic_area || "").toLowerCase().includes(q)
  );
}

/**
 * Get a drug by exact name (case-insensitive).
 * @param {string} name
 * @returns {object|null}
 */
export function getDrug(name) {
  if (!name) return null;
  const n = name.toLowerCase();
  return DRUGS.find(d =>
    d.name.toLowerCase() === n ||
    d.generic_name.toLowerCase() === n ||
    (d.brand_names || []).some(b => b.toLowerCase() === n)
  ) || null;
}

/**
 * Get all drugs in a therapeutic class.
 * @param {string} drugClass
 * @returns {Array}
 */
export function getDrugsByClass(drugClass) {
  if (!drugClass) return DRUGS;
  const c = drugClass.toLowerCase();
  return DRUGS.filter(d =>
    (d.drug_class || "").toLowerCase().includes(c) ||
    (d.therapeutic_area || "").toLowerCase().includes(c)
  );
}

/**
 * Check known interaction between two drugs.
 * Returns a synthetic interaction assessment based on drug class data.
 * @param {string} drugA
 * @param {string} drugB
 * @returns {object}
 */
export function getDrugInteractions(drugA, drugB) {
  const a = getDrug(drugA);
  const b = getDrug(drugB);
  if (!a || !b) {
    return { error: "One or both drugs not found", drugA, drugB };
  }

  // Known high-risk class interactions
  const INTERACTIONS = [
    { classA: "MAOI", classB: "SSRI", severity: "contraindicated", description: "Serotonin syndrome risk — washout 14 days required" },
    { classA: "MAOI", classB: "SNRI", severity: "contraindicated", description: "Serotonin syndrome risk — washout 14 days required" },
    { classA: "ACE Inhibitor", classB: "Angiotensin Receptor Blocker", severity: "major", description: "Dual RAS blockade increases hyperkalemia and renal impairment risk" },
    { classA: "ACE Inhibitor", classB: "Angiotensin Receptor-Neprilysin Inhibitor", severity: "contraindicated", description: "Angioedema risk — 36h washout required" },
    { classA: "Anticoagulant", classB: "Antiplatelet", severity: "major", description: "Increased bleeding risk; monitor closely" },
    { classA: "Statin", classB: "Fibrate", severity: "moderate", description: "Myopathy/rhabdomyolysis risk increased" },
    { classA: "QT-prolonging", classB: "QT-prolonging", severity: "major", description: "Additive QT prolongation, torsades de pointes risk" },
    { classA: "Opioid", classB: "Benzodiazepine", severity: "major", description: "Respiratory depression, death risk — FDA black box warning" },
    { classA: "Opioid", classB: "CNS Depressant", severity: "major", description: "Additive CNS/respiratory depression" },
    { classA: "NSAID", classB: "Anticoagulant", severity: "major", description: "Increased GI bleeding risk" },
    { classA: "NSAID", classB: "ACE Inhibitor", severity: "moderate", description: "Reduced antihypertensive effect; renal impairment risk" },
    { classA: "TNF Inhibitor", classB: "JAK Inhibitor", severity: "major", description: "Serious infection risk with combined immunosuppression" },
    { classA: "Biguanide", classB: "Iodinated Contrast", severity: "major", description: "Lactic acidosis risk — hold metformin 48h before/after" },
    { classA: "SSRI", classB: "NSAID", severity: "moderate", description: "Increased GI bleed risk; consider gastroprotection" },
    { classA: "Insulin", classB: "Beta-blocker", severity: "moderate", description: "Beta-blockers mask hypoglycemic symptoms" },
    { classA: "Antifungal", classB: "Statin", severity: "major", description: "Azole antifungals inhibit CYP3A4; increases statin exposure; myopathy risk" },
    { classA: "PCSK9 Inhibitor", classB: "Statin", severity: "none", description: "Complementary LDL-lowering; no adverse interaction" },
    { classA: "Opioid", classB: "MAO Inhibitor", severity: "contraindicated", description: "Serotonin syndrome / opioid toxicity — meperidine MAOI is classic lethal combo" },
    { classA: "Anticoagulant", classB: "NSAID", severity: "major", description: "Significantly increased bleeding risk — GI hemorrhage" },
    { classA: "Direct Oral Anticoagulant", classB: "P-gp Inhibitor", severity: "major", description: "Increased DOAC exposure; bleeding risk" },
  ];

  const classA = (a.drug_class || "").toLowerCase();
  const classB = (b.drug_class || "").toLowerCase();

  let interactions = [];
  for (const ix of INTERACTIONS) {
    const matchA = classA.includes(ix.classA.toLowerCase()) && classB.includes(ix.classB.toLowerCase());
    const matchB = classB.includes(ix.classA.toLowerCase()) && classA.includes(ix.classB.toLowerCase());
    if (matchA || matchB) {
      interactions.push({
        severity: ix.severity,
        description: ix.description,
        drug_a_class: a.drug_class,
        drug_b_class: b.drug_class,
      });
    }
  }

  return {
    drug_a: { name: a.name, drug_class: a.drug_class },
    drug_b: { name: b.name, drug_class: b.drug_class },
    interaction_found: interactions.length > 0,
    interactions,
    overall_severity: interactions.length > 0
      ? (interactions.some(i => i.severity === "contraindicated") ? "contraindicated"
        : interactions.some(i => i.severity === "major") ? "major"
        : interactions.some(i => i.severity === "moderate") ? "moderate"
        : "minor")
      : "none",
    recommendation: interactions.length === 0
      ? "No known major class interaction identified. Always verify with a pharmacist."
      : interactions[0].severity === "contraindicated"
        ? "CONTRAINDICATED: Do not use together."
        : interactions[0].severity === "major"
          ? "MAJOR: Use only if benefit outweighs risk; monitor closely."
          : "MODERATE: Use with caution; monitor patient.",
  };
}
